#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n;
    int k;
    cin >> n >> k;

    vector<int> base_digits;
    while (n > 0) {
        base_digits.push_back(n % k);
        n /= k;
    }

    vector<vector<long long>> mat(k + 1, vector<long long>(k + 1, 0));
    for (int j = 0; j <= k; ++j) {
        mat[0][j] = 1;
        mat[j][j] = 1;
    }

    auto mat_mult = [&](const vector<vector<long long>> &A, const vector<vector<long long>> &B) {
        vector<vector<long long>> res(k + 1, vector<long long>(k + 1, 0));
        for (int i = 0; i <= k; ++i)
            for (int j = 0; j <= k; ++j)
                for (int l = 0; l <= k; ++l)
                    res[i][j] = (res[i][j] + A[i][l] * B[l][j]) % 1000000007;
        return res;
    };

    auto mat_pow = [&](vector<vector<long long>> base, long long exp) {
        vector<vector<long long>> result(k + 1, vector<long long>(k + 1, 0));
        for (int i = 0; i <= k; ++i) result[i][i] = 1;
        while (exp > 0) {
            if (exp & 1) result = mat_mult(result, base);
            base = mat_mult(base, base);
            exp >>= 1;
        }
        return result;
    };

    vector<vector<long long>> A = mat;
    long long sum = 0;
    for (int i = (int)base_digits.size() - 1; i >= 0; --i) {
        for (int j = 0; j < base_digits[i]; ++j) {
            auto temp = mat_pow(A, (j + sum) % k);
            for (int x = 0; x <= k; ++x)
                for (int y = 0; y <= k; ++y)
                    mat[x][y] = (mat[x][y] + temp[x][y]) % 1000000007;
        }
        sum = (sum + base_digits[i]) % k;
    }

    long long result = 0;
    for (int i = 0; i <= k; ++i) {
        result = (result + mat[i][k]) % 1000000007;
    }
    cout << result << "\n";
    return 0;
}
